"""Write reports/presentation_results.md from files in results/ (no number is typed by hand).

Usage:  python -m src.report_presentation
"""
from __future__ import annotations

import json

import pandas as pd

from src.config import path
from src.eval.report import to_markdown


def main() -> None:
    res = path("results")
    lines = ["# Results for the 9 Nov presentation", "",
             "Generated by `src/report_presentation.py` from `results/`. Research prototype, not for clinical use.", ""]

    audit = (res / "data_audit.md").read_text().splitlines() if (res / "data_audit.md").exists() else []
    keep = [l for l in audit if l.startswith("- ") and any(k in l for k in ["Raw shape", "duplicate", "== 0", "Target rate", "slope"])]
    lines += ["## Data audit (Stage 1)", "", *keep, ""]

    if (res / "table4_models.csv").exists():
        t4 = pd.read_csv(res / "table4_models.csv")
        e1 = json.loads((res / "e1_summary.json").read_text())
        comp = pd.read_csv(res / "model_comparison.csv")
        lines += ["## RC1 — model comparison (Table 4)", "",
                  to_markdown(t4[["Model", "CV ROC-AUC", "Test ROC-AUC (95% CI)", "Sensitivity (95% CI)",
                                  "Specificity (95% CI)", "Brier (95% CI)", "Cal. slope"]]), "",
                  f"- Best single model by nested-CV ROC-AUC: **{e1['best_by_cv']}**; ensembles built from {e1['top3']}.",
                  f"- SHAP (on {e1['explanations']['best_tree']}): top attributes {e1['explanations']['shap_top']}."]
        for _, r in comp.iterrows():
            lines.append(f"- {r.comparison}: ΔAUC {r.delta_auc:+.3f} (95% CI {r.ci_lo:+.3f} to {r.ci_hi:+.3f}), p = {r.p_value:.3f}")
        lines += ["- Figures: `results/figures/fig1_roc.png`, `fig2_pr.png`, `fig3_calibration.png`, `fig4_shap_summary.png`", ""]

    if (res / "sanity.md").exists():
        s = (res / "sanity.md").read_text().splitlines()
        lines += ["## Sanity checks", "", *[l for l in s if l.startswith("- ")], ""]

    if (res / "table5_tiers_display.csv").exists():
        t5 = pd.read_csv(res / "table5_tiers_display.csv")
        e2 = json.loads((res / "e2_summary.json").read_text())
        lines += ["## RC2 — test availability (Table 5)", "", to_markdown(t5), "",
                  f"- Decision curves (Figure 5) use {e2['dca_model']}; counterfactuals use the best T2 model, "
                  f"{e2['best_T2']} (`results/counterfactual_examples.md`).", ""]

    if (res / "tabpfn_status.md").exists():
        lines += ["## Notes", "", *[l for l in (res / "tabpfn_status.md").read_text().splitlines()[2:] if l], ""]
    (path("reports") / "presentation_results.md").write_text("\n".join(lines) + "\n")
    print("wrote", path("reports") / "presentation_results.md")


if __name__ == "__main__":
    main()
